        if x <= 1:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def fibonacci():
        a, b = 0, 1
        while True:
            a, b = b, a + b
            yield a

    prime_fibs = []
    for fib_num in fibonacci():
        if is_prime(fib_num):
            prime_fibs.append(fib_num)
            if len(prime_fibs) == n:
                return fib_num

